#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — deploy 前置：证书、deploy 密钥、仓库变量/密钥、首发自检
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
cd "$(cd "$(dirname "$0")/.." && pwd)"   # gh secret/variable 依赖仓库根目录
ENV_FILE="${DP_ENV_FILE:-deploy/.env.acceptance}"
SSH_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)
SCP_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)

remote() { ssh "${SSH_OPTS[@]}" "$ECS_SSH" "$@"; }

banner "云河FC 部署前置（首次 RC 发布）"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "目标确认"
while :; do
  ask RC_DOMAIN "生产域名（不含 www）[yunhefc.com]："
  RC_DOMAIN="${RC_DOMAIN:-yunhefc.com}"
  if [[ "$RC_DOMAIN" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]] \
      && [[ "$RC_DOMAIN" != www.* ]]; then
    break
  fi
  warn "域名必须是小写裸域名（如 yunhefc.com），不带 www./scheme/路径/端口"
done
ask ECS_SSH "ECS root SSH 目标（装证书与密钥用）[root@47.116.72.163]："
ECS_SSH="${ECS_SSH:-root@47.116.72.163}"
ECS_IP="${ECS_SSH#*@}"
ask ECS_USER "CI 登录用户（docker 组、无 sudo）[deploy]："
ECS_USER="${ECS_USER:-deploy}"
ask ECS_PORT "SSH 端口 [22]："
ECS_PORT="${ECS_PORT:-22}"
SSH_OPTS+=(-p "$ECS_PORT")
SCP_OPTS+=(-P "$ECS_PORT")
# 默认取 origin/main 的 sha7：沿用硬编码旧提交会把落后多天的代码发到生产。
MAIN_SHA7=$(git rev-parse --short=7 origin/main 2>/dev/null || git rev-parse --short=7 HEAD 2>/dev/null || true)
while :; do
  ask SHA7 "要部署的 commit sha7 [${MAIN_SHA7:-unknown}]："
  SHA7="${SHA7:-$MAIN_SHA7}"
  # 只允许 7 位小写十六进制：该值会拼进远端 shell 命令，必须挡住注入。
  if [[ "$SHA7" =~ ^[0-9a-f]{7}$ ]]; then break; fi
  warn "sha7 必须是 7 位小写十六进制（git rev-parse --short=7 origin/main）"
  SHA7=""
done
if [[ -n "$MAIN_SHA7" && "$SHA7" != "$MAIN_SHA7" ]]; then
  warn "所选 sha7 与 origin/main（${MAIN_SHA7}）不一致"
  confirm "仍要部署 ${SHA7}？" || { warn "已取消"; exit 1; }
fi
write_env RC_DOMAIN "$RC_DOMAIN"
write_env ECS_SSH "$ECS_SSH"
write_env ECS_USER "$ECS_USER"
write_env ECS_PORT "$ECS_PORT"
write_env SHA7 "$SHA7"

if remote 'echo ok' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} SSH 可用：$ECS_SSH"
else
  warn "SSH 不可用，后续阶段无法继续"
  SKIPPED+=("ECS SSH $ECS_SSH")
fi
if remote "id -u '$ECS_USER'" >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} 用户 $ECS_USER 存在"
  if remote "id -nG '$ECS_USER' | tr ' ' '\n' | grep -qx docker" >/dev/null 2>&1; then
    say "  ${GREEN}✓${RESET} $ECS_USER 在 docker 组"
  else
    warn "$ECS_USER 不在 docker 组，release.sh 会失败"
    SKIPPED+=("把 $ECS_USER 加入 docker 组")
  fi
else
  warn "用户 $ECS_USER 不存在"
  SKIPPED+=("创建 ECS 用户 $ECS_USER")
fi

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "TLS 证书"
say "nginx 固定读取 /opt/yunhefc/certs/{fullchain,privkey}.pem，证书只需覆盖 www.${RC_DOMAIN}；裸域/旧子域不提供 HTTPS。"
CERT_READY=0
if remote 'test -s /opt/yunhefc/certs/fullchain.pem && test -s /opt/yunhefc/certs/privkey.pem' >/dev/null 2>&1; then
  say "  主机已有证书："
  remote 'openssl x509 -in /opt/yunhefc/certs/fullchain.pem -noout -subject -enddate' 2>/dev/null | sed 's/^/    /' || true
  # 仅“文件非空”不算就绪：过期 / SAN 不覆盖 / 私钥不匹配都会让 TLS 与微信回调失败。
  cert_ok=1
  if ! remote 'openssl x509 -in /opt/yunhefc/certs/fullchain.pem -noout -checkend 2592000' >/dev/null 2>&1; then
    warn "现有证书剩余 ≤30 天或无法解析"
    cert_ok=0
  fi
  san_lines=$(remote 'openssl x509 -in /opt/yunhefc/certs/fullchain.pem -noout -ext subjectAltName' 2>/dev/null \
    | tr ', ' '\n\n' | sed '/^$/d' || true)
  if ! printf '%s\n' "$san_lines" | grep -Fqx "DNS:www.$RC_DOMAIN" \
      && ! printf '%s\n' "$san_lines" | grep -Fqx "DNS:*.$RC_DOMAIN"; then
    warn "现有证书 SAN 未覆盖 www.$RC_DOMAIN"
    cert_ok=0
  fi
  if ! remote 'test "$(openssl x509 -in /opt/yunhefc/certs/fullchain.pem -noout -pubkey)" = "$(openssl pkey -in /opt/yunhefc/certs/privkey.pem -pubout 2>/dev/null)"' >/dev/null 2>&1; then
    warn "现有证书与私钥不匹配，nginx 会起不来"
    cert_ok=0
  fi
  if (( cert_ok )); then
    if confirm "沿用现有证书？"; then
      CERT_READY=1
    fi
  else
    warn "现有证书不可沿用，请重新上传"
  fi
fi
if (( CERT_READY )); then
  say "  ${GREEN}✓${RESET} 沿用现有证书"
else
  ask CERT_FULLCHAIN "本地 fullchain.pem 路径："
  ask CERT_PRIVKEY "本地 privkey.pem 路径："
  CERT_FULLCHAIN="${CERT_FULLCHAIN/#\~/$HOME}"
  CERT_PRIVKEY="${CERT_PRIVKEY/#\~/$HOME}"
  if [[ -f "$CERT_FULLCHAIN" && -f "$CERT_PRIVKEY" ]]; then
    if openssl x509 -in "$CERT_FULLCHAIN" -noout -checkend 2592000 >/dev/null 2>&1; then
      say "  ${GREEN}✓${RESET} 证书剩余 >30 天"
    else
      warn "证书剩余 ≤30 天或无法解析"
    fi
    san_lines=$(openssl x509 -in "$CERT_FULLCHAIN" -noout -ext subjectAltName 2>/dev/null \
      | tr ', ' '\n\n' | sed '/^$/d' || true)
    if printf '%s\n' "$san_lines" | grep -Fqx "DNS:www.$RC_DOMAIN" \
        || printf '%s\n' "$san_lines" | grep -Fqx "DNS:*.$RC_DOMAIN"; then
      say "  ${GREEN}✓${RESET} SAN 覆盖 www.$RC_DOMAIN"
    else
      warn "SAN 未覆盖 www.${RC_DOMAIN}，浏览器会报证书错误"
      SKIPPED+=("证书 SAN 覆盖 www.$RC_DOMAIN")
    fi
    scp "${SCP_OPTS[@]}" "$CERT_FULLCHAIN" "$ECS_SSH:/opt/yunhefc/certs/fullchain.pem"
    scp "${SCP_OPTS[@]}" "$CERT_PRIVKEY"   "$ECS_SSH:/opt/yunhefc/certs/privkey.pem"
    remote "chown '$ECS_USER:$ECS_USER' /opt/yunhefc/certs/fullchain.pem /opt/yunhefc/certs/privkey.pem"
    remote 'chmod 644 /opt/yunhefc/certs/fullchain.pem; chmod 600 /opt/yunhefc/certs/privkey.pem'
    say "  ${GREEN}✓${RESET} 证书已上传到 /opt/yunhefc/certs"
  else
    warn "证书文件不存在，跳过；nginx 起不来"
    SKIPPED+=("TLS 证书上传")
  fi
  open_url "https://yundun.console.aliyun.com/?p=cas"
  step "如无证书，在数字证书管理服务申请覆盖 www.${RC_DOMAIN} 的证书后重跑本阶段。"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "deploy 用户 SSH 密钥"
KEY_PATH_DEFAULT="$HOME/.ssh/yunhefc_deploy_ed25519"
ask DEPLOY_KEY "deploy 私钥路径（不存在则生成新 ed25519）[$KEY_PATH_DEFAULT]："
DEPLOY_KEY="${DEPLOY_KEY:-$KEY_PATH_DEFAULT}"
# 展开 ~：否则会在仓库工作区里生成字面量 "~/..." 目录并把私钥写进去。
DEPLOY_KEY="${DEPLOY_KEY/#\~/$HOME}"
write_env DEPLOY_KEY "$DEPLOY_KEY"
if [[ -f "$DEPLOY_KEY" ]]; then
  say "  ${GREEN}✓${RESET} 复用现有私钥：$DEPLOY_KEY"
  chmod 600 "$DEPLOY_KEY" 2>/dev/null || true
else
  mkdir -p "$(dirname "$DEPLOY_KEY")"
  ssh-keygen -t ed25519 -C "yunhefc-deploy" -N "" -f "$DEPLOY_KEY" >/dev/null
  say "  ${GREEN}✓${RESET} 已生成密钥对：$DEPLOY_KEY"
  note "私钥不写入仓库；丢弃前请确认 ECS_SSH_KEY 已写入 GitHub"
fi
PUB_KEY=""
if PUB_KEY="$(ssh-keygen -y -f "$DEPLOY_KEY" 2>/dev/null)"; then
  say "  ${GREEN}✓${RESET} 已从私钥导出公钥"
else
  PUB_KEY=""
  warn "无法从 $DEPLOY_KEY 导出公钥（是否有口令？）"
  SKIPPED+=("安装 deploy 公钥")
fi
KEY_VERIFIED=0
if [[ -n "$PUB_KEY" ]]; then
  say "  将写入 /home/$ECS_USER/.ssh/authorized_keys（覆盖旧内容）"
  if confirm "确认安装公钥？"; then
    remote "install -d -m 700 -o '$ECS_USER' -g '$ECS_USER' '/home/$ECS_USER/.ssh'"
    printf '%s\n' "$PUB_KEY" | remote "umask 077; cat > '/home/$ECS_USER/.ssh/authorized_keys'"
    remote "chown '$ECS_USER:$ECS_USER' '/home/$ECS_USER/.ssh/authorized_keys'; chmod 600 '/home/$ECS_USER/.ssh/authorized_keys'"
    if ssh -i "$DEPLOY_KEY" -p "$ECS_PORT" -o BatchMode=yes -o StrictHostKeyChecking=no \
         -o UserKnownHostsFile=/dev/null "$ECS_USER@$ECS_IP" 'docker ps' >/dev/null 2>&1; then
      say "  ${GREEN}✓${RESET} $ECS_USER@$ECS_IP SSH + docker 可用"
      KEY_VERIFIED=1
    else
      warn "SSH 测试失败：检查密钥、用户与 docker 组"
      SKIPPED+=("验证 $ECS_USER SSH 登录")
    fi
  else
    warn "跳过公钥安装"
    SKIPPED+=("安装 deploy 公钥")
  fi
fi
if (( ! KEY_VERIFIED )) && ssh -i "$DEPLOY_KEY" -p "$ECS_PORT" -o BatchMode=yes \
     -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \
     "$ECS_USER@$ECS_IP" 'docker ps' >/dev/null 2>&1; then
  # 没装新公钥但现有私钥能登录：说明 ECS 端已有对应公钥，可以安全写入 CI。
  say "  ${GREEN}✓${RESET} 现有私钥已可登录 $ECS_USER@$ECS_IP"
  KEY_VERIFIED=1
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "GitHub 仓库变量与密钥"
HOST_KEYS="$(ssh-keyscan -p "$ECS_PORT" -t ed25519 "$ECS_IP" 2>/dev/null || true)"
if [[ -z "$HOST_KEYS" ]]; then
  warn "ssh-keyscan 未取到主机指纹"
  SKIPPED+=("ECS_KNOWN_HOSTS（手工 ssh-keyscan）")
else
  say "  主机指纹："
  printf '%s\n' "$HOST_KEYS" | ssh-keygen -lf - 2>/dev/null | sed 's/^/    /' || true
  if confirm "指纹可信，写入 ECS_KNOWN_HOSTS？"; then
    set_secret ECS_KNOWN_HOSTS "$HOST_KEYS"
  else
    warn "跳过 ECS_KNOWN_HOSTS"
    SKIPPED+=("GitHub secret ECS_KNOWN_HOSTS")
  fi
fi

set_var ECS_HOST "$ECS_IP"
set_var ECS_USER "$ECS_USER"
set_var ECS_PORT "$ECS_PORT"

# 只有私钥确实能登录时才覆盖 ECS_SSH_KEY，否则会把本来可用的 CI 密钥换成不可用的。
if (( KEY_VERIFIED )); then
  set_secret ECS_SSH_KEY "$(<"$DEPLOY_KEY")"
else
  warn "私钥未通过登录验证，保留现有 ECS_SSH_KEY"
  SKIPPED+=("GitHub secret ECS_SSH_KEY（未验证私钥）")
fi

ask DEPLOY_WEBHOOK_URL "钉钉/企微 webhook（可留空）："
if [[ -n "$DEPLOY_WEBHOOK_URL" ]]; then
  set_secret DEPLOY_WEBHOOK_URL "$DEPLOY_WEBHOOK_URL"
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "首发自检"
if remote 'test -s /opt/yunhefc/certs/fullchain.pem && test -s /opt/yunhefc/certs/privkey.pem' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} 主机证书就位"
else
  warn "主机证书缺失"; SKIPPED+=("主机证书")
fi
if remote 'test -s /opt/yunhefc/.env && stat -c %a /opt/yunhefc/.env | grep -qx 600' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} /opt/yunhefc/.env 存在且为 600"
else
  warn "/opt/yunhefc/.env 缺失或权限不是 600"; SKIPPED+=("生产 .env")
fi
if ssh -i "$DEPLOY_KEY" -p "$ECS_PORT" -o BatchMode=yes -o StrictHostKeyChecking=no \
     -o UserKnownHostsFile=/dev/null "$ECS_USER@$ECS_IP" 'docker ps' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} CI 身份可登录"
else
  warn "CI 身份无法登录"; SKIPPED+=("CI SSH 登录")
fi
if ssh -i "$DEPLOY_KEY" -p "$ECS_PORT" -o BatchMode=yes -o StrictHostKeyChecking=no \
     -o UserKnownHostsFile=/dev/null "$ECS_USER@$ECS_IP" \
     'set -a; . /opt/yunhefc/env/acr.env; set +a
      printf "%s" "$ACR_PASSWORD" | docker login "$ACR_REGISTRY" -u "$ACR_USERNAME" --password-stdin >/dev/null
      for n in yunhefc-backend yunhefc-nginx; do
        docker manifest inspect "$ACR_REGISTRY/$ACR_NAMESPACE/$n:sha-'"$SHA7"'" >/dev/null || exit 1
      done' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} 双镜像 sha-$SHA7 存在且 $ECS_USER 可拉取"
else
  warn "镜像 sha-$SHA7 缺失或 $ECS_USER 无法登录 ACR"; SKIPPED+=("镜像 sha-$SHA7")
fi

say ""
say "下一步（首发）："
note "1. gh workflow run deploy.yml -f sha=$SHA7 --ref main   # production Environment 只允许 main"
note "2. 在 Actions 页面批准 production Environment"
note "3. 发布后跑 scripts/rc-acceptance-wizard.sh 并回填 release-checklist"

finish

